// Bundle-drift guard for the native clients.
//
// The web/desktop app imports @inbox2/email-body source directly (vite alias), so it
// can never be stale. The native clients instead run a BUILT copy of the bundle:
//   - Android ships ui/android/.../assets/email-body.js — COMMITTED to git, so it can
//     drift if someone changes src/ and forgets to rebuild it. That is exactly the bug
//     that left Android without the <pre>-unwrap fix. This is the hard guard below.
//   - iOS ships ui/ios/Resources/email-body.js — gitignored, regenerated from src/ by
//     ui/ios/bootstrap.sh on every bootstrap, so it can't drift in git. Checked softly
//     (only when present locally).
//
// Comparison ignores esbuild's source-path comments (`// src/index.js` vs
// `// ../../packages/email-body/src/index.js`) so it's invariant to which working
// directory built the bundle — only real logic drift fails it.
//
// Fix a failure by running:  bin/sync-email-body
import { describe, it, expect, beforeAll } from 'vitest';
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { createRequire } from 'node:module';

const here = path.dirname(fileURLToPath(import.meta.url));
const pkgDir = path.resolve(here, '..');
const repoRoot = path.resolve(pkgDir, '../..');

const require = createRequire(import.meta.url);
const esbuild = require(require.resolve('esbuild', { paths: [path.join(repoRoot, 'ui/web')] }));

// Strip the directory prefix from esbuild's per-module path comments so a bundle
// built from any cwd normalizes to the same text. Logic differences survive this.
const norm = (s) => s.replace(/\/\/ (?:[^\n]*\/)?(src\/[\w.]+\.js)/g, '// $1');
const readNorm = (p) => norm(readFileSync(p, 'utf8'));

const ANDROID = path.join(repoRoot, 'ui/android/app/src/main/assets/email-body.js');
const IOS = path.join(repoRoot, 'ui/ios/Resources/email-body.js');
const DIST = path.join(pkgDir, 'dist/email-body.js');

describe('email-body bundle sync', () => {
  let canonical;
  beforeAll(async () => {
    const result = await esbuild.build({
      absWorkingDir: pkgDir,
      entryPoints: ['src/index.js'],
      bundle: true,
      format: 'iife',
      globalName: 'Inbox2EmailBody',
      write: false,
    });
    canonical = norm(result.outputFiles[0].text);
  });

  it('the committed Android bundle matches a fresh build of src/ (run bin/sync-email-body)', () => {
    expect(readNorm(ANDROID)).toBe(canonical);
  });

  it('the iOS bundle matches src/ when present (generated by ui/ios/bootstrap.sh)', () => {
    if (!existsSync(IOS)) return; // gitignored — absent on a fresh checkout until bootstrap
    expect(readNorm(IOS)).toBe(canonical);
  });

  it('the built dist matches src/ when present', () => {
    if (!existsSync(DIST)) return; // gitignored build artifact
    expect(readNorm(DIST)).toBe(canonical);
  });
});
